import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.when;

public class TextNodeTest {

    private TextNode textNode = new TextNode("text");

    @Test
    public void nodeName_GivenText_ReturnsText() {
        assertEquals("text", textNode.nodeName());
    }

    @Test
    public void text_GivenText_RetainsOriginalText() {
        when(textNode.text()).thenReturn("original text");
        String actual = textNode.text();
        assertEquals("original text", actual);
    }

    @Test
    public void text_GivenNull_ReturnsBlank() {
        when(textNode.text()).thenReturn(null);
        assertTrue(TextNode.normalizeWhitespace(textNode.text()));
    }

    @Test
    public void getWholeText_GivenText_ReturnsText() {
        assertEquals("text", textNode.getWholeText());
    }

    @Test
    public void isBlank_GivenEmptyText_ReturnsTrue() {
        when(textNode.text()).thenReturn("");
        assertTrue(textNode.isBlank());
    }

    @Test
    public void isBlank_GivenNonEmptyText_ReturnsFalse() {
        when(textNode.text()).thenReturn("text");
        assertFalse(textNode.isBlank());
    }

    @Test
    public void splitText_CalledWithOffset_ReturnsNewTextNode() {
        TextNode newTextNode = textNode.splitText(1);
        assertNotNull(newTextNode);
    }

    @Test
    public void outerHtmlHead_GivenAccumDepthOutSettingsThrowsIOException() {
        Appendable accum = Mockito.mock(Appendable.class);
        Document.OutputSettings out = Mockito.mock(Document.OutputSettings.class);
        when(out.depth()).thenReturn(0);
        when(accum.toString()).thenThrow(new IOException());
        TextNode textNode = new TextNode("text");
        try {
            textNode.outerHtmlHead(accum, 1, out);
            fail("IOException was not thrown");
        } catch (IOException e) {
            // expected
        }
    }

    @Test
    public void outerHtmlTail_GivenAccumDepthOutSettingsThrowsIOException() {
        Appendable accum = Mockito.mock(Appendable.class);
        Document.OutputSettings out = Mockito.mock(Document.OutputSettings.class);
        when(out.depth()).thenReturn(0);
        when(accum.toString()).thenThrow(new IOException());
        TextNode textNode = new TextNode("text");
        try {
            textNode.outerHtmlTail(accum, 1, out);
            fail("IOException was not thrown");
        } catch (IOException e) {
            // expected
        }
    }

    @Test
    public void clone_GivenTextNode_ReturnsClone() {
        TextNode cloned = textNode.clone();
        assertNotNull(cloned);
    }

    @Test
    public void createFromEncoded_GivenEncodedText_ReturnsTextNode() {
        TextNode textNode = TextNode.createFromEncoded("encoded text");
        assertNotNull(textNode);
    }

    @Test
    public void stripLeadingWhitespace_GivenText_ReturnsNormalisedText() {
        String result = TextNode.stripLeadingWhitespace("   text");
        assertEquals("text", TextNode.normaliseWhitespace(result));
    }
}
